h='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Installed crew motion comparison</title><style>body{background:#172226;color:#dbe4df;font:17px system-ui;margin:24px}button,select{font:inherit;padding:8px}.wrap{overflow:auto}canvas{width:1200px;height:720px;display:block}</style><h1>Installed crew motion comparison</h1><p>Actual installed PNGs and timing. Browser playback; native snapshots linked below. James west cadence remains provisional.</p><button id="pause">Pause</button> <select id="mode"><option value="walk">Walk</option><option value="idle">Idle</option><option value="transition">Idle / walk</option></select> <select id="size"><option value="82">82px close</option><option value="54">54px middle</option><option value="27">27px wide</option><option value="148">148px inspection</option></select><p id="status">Loading…</p><div class="wrap"><canvas width="1200" height="720"></canvas></div><p><a style="color:#a5dce0" href="../crew-installed-direction-check-v1/">Native Godot snapshots</a></p><script>const tracks=TRACKS;let ready=false,t=0,last=0,playing=true;const ctx=document.querySelector('canvas').getContext('2d');function load(src,n=0){return new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=()=>n<3?setTimeout(()=>load(src,n+1).then(resolve,reject),300):reject(Error(src));im.src=src})}async function init(){for(const s of tracks){for(const k of ['idle','walk']){const st=s.states[k];st.images=await Promise.all(st.files.map(f=>load(f)));st.total=st.durations.reduce((a,b)=>a+b,0)}}ready=true;document.querySelector('#status').textContent='All installed frames loaded'}init().catch(()=>document.querySelector('#status').textContent='Image load failed; reload to retry');document.querySelector('#pause').onclick=e=>{playing=!playing;e.target.textContent=playing?'Pause':'Play'};function draw(now){if(last&&playing)t+=now-last;last=now;if(ready){ctx.fillStyle='#303b40';ctx.fillRect(0,0,1200,720);const mode=document.querySelector('#mode').value;const family=mode==='transition'?(Math.floor(t/2200)%2?'walk':'idle'):mode;const z=Number(document.querySelector('#size').value)/148;ctx.imageSmoothingEnabled=true;for(const s of tracks){const st=s.states[family];let q=t%st.total,i=0;while(i<st.images.length-1&&q>=st.durations[i])q-=st.durations[i++];const x=s.col*300,y=s.row*240;ctx.fillStyle='#dbe4df';ctx.font='17px system-ui';ctx.fillText(s.label+' · '+family,x+15,y+28);ctx.strokeStyle='#62757a';ctx.beginPath();ctx.moveTo(x+45,y+210);ctx.lineTo(x+255,y+210);ctx.stroke();ctx.drawImage(st.images[i],x+150-92*z,y+210-172*z,184*z,184*z)}}requestAnimationFrame(draw)}requestAnimationFrame(draw)</script>''';(P/'index.html').write_text(h.replace('TRACKS',json.dumps(tracks)),encoding='utf-8');print('12 installed directional pairs; references exist:',all((P/f).exists() for t in tracks for s in t['states'].values() for f in s['files']))
